
"""Privacy-safe, image-level pipeline instrumentation (task 3.9a)."""

import logging
from contextlib import contextmanager
from contextvars import ContextVar
from time import perf_counter

logger = logging.getLogger("brandlens.pipeline")

# Identifiers are generated by the application and must not be file paths.
_CURRENT_IMAGE: ContextVar[tuple[str, str] | None] = ContextVar(
    "brandlens_current_image", default=None
)


@contextmanager
def track_stage(job_id: str, image_id: str, stage: str):
    """Log stage progress, duration, and failures."""

    start = perf_counter()

    logger.info(
        "job=%s image=%s stage=%s status=started",
        job_id,
        image_id,
        stage,
    )

    try:
        yield

    except Exception as exc:
        elapsed_ms = (perf_counter() - start) * 1000

        logger.warning(
            "job=%s image=%s stage=%s status=failed "
            "duration_ms=%.1f error_type=%s",
            job_id,
            image_id,
            stage,
            elapsed_ms,
            type(exc).__name__,
        )
        raise

    else:
        elapsed_ms = (perf_counter() - start) * 1000

        logger.info(
            "job=%s image=%s stage=%s status=completed "
            "duration_ms=%.1f",
            job_id,
            image_id,
            stage,
            elapsed_ms,
        )

@contextmanager
def image_logging_context(job_id: str, image_id: str):
    """Bind generated job/image IDs for nested pipeline functions.

    ContextVar is scoped to the current execution context and reset after
    processing so concurrent jobs do not inherit another image's identifiers.
    """
    token = _CURRENT_IMAGE.set((job_id, image_id))
    try:
        yield
    finally:
        _CURRENT_IMAGE.reset(token)


@contextmanager
def track_current_stage(stage: str):
    """Track a nested stage if an image context is active; otherwise just run."""
    identifiers = _CURRENT_IMAGE.get()
    if identifiers is None:
        yield
    else:
        with track_stage(identifiers[0], identifiers[1], stage):
            yield


def log_image_event(stage: str, status: str, *, reason: str | None = None) -> None:
    """Log safe statuses and allowlisted reasons without raw image/file data."""
    identifiers = _CURRENT_IMAGE.get()
    if identifiers is None:
        return
    job_id, image_id = identifiers
    safe_reasons = {
        "animated", "too_many_pixels", "unsupported_format", "too_small",
        "extreme_aspect_ratio", "unprocessable",
    }
    if reason is None:
        logger.info(
            "job=%s image=%s stage=%s status=%s",
            job_id, image_id, stage, status,
        )
    else:
        logger.info(
            "job=%s image=%s stage=%s status=%s reason=%s",
            job_id, image_id, stage, status,
            reason if reason in safe_reasons else "other",
        )
